ss="linha-registro"><span><b><?= e($o['public_code']) ?> · <?= e($o['customer_name']) ?></b><small><?= e($o['payment_method']) ?> · <?= e($o['status']) ?></small></span><strong><?= $money((int)$o['total_cents']) ?></strong></div><?php endforeach;endif;?></article></form></main><script src="/assets/admin-ui.js?v=20260903-review1" defer></script></body></html>

